import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

import type { AvatarMime } from "@/domain/media/image";

/**
 * Where hero profile-photo BYTES live. The database only ever holds a path + integrity metadata (never the image),
 * so the database stays small and the images can sit on a CDN-friendly object store.
 *
 *   production  → Supabase Storage (private bucket, server-side service-role access)
 *   local dev   → files on disk next to the embedded database
 *   tests       → in memory
 *
 * Object paths are generated by the server from ids and content hashes (`override/<heroId>/<sha16>.png`) — a
 * client-supplied file name never reaches storage.
 */

export interface AvatarStore {
  readonly kind: "supabase" | "local" | "memory";
  put(path: string, bytes: Uint8Array, mime: AvatarMime): Promise<void>;
  get(path: string): Promise<Uint8Array | null>;
  remove(path: string): Promise<void>;
}

export class StorageError extends Error {
  constructor(
    message: string,
    readonly status?: number,
  ) {
    super(message);
    this.name = "StorageError";
  }
}

/** Same shape the database CHECK enforces. No leading slash, no empty or dot segments, no backslashes. */
const SAFE_PATH = /^[a-z0-9][a-z0-9/_.-]{3,200}$/;

export function isSafeStoragePath(p: string): boolean {
  return SAFE_PATH.test(p) && !p.includes("//") && p.split("/").every((seg) => seg !== "." && seg !== ".." && seg !== "");
}

function assertSafe(p: string): void {
  if (!isSafeStoragePath(p)) throw new StorageError("unsafe storage path");
}

// ---------------------------------------------------------------------------------------

export function createMemoryAvatarStore(): AvatarStore & { files: Map<string, Uint8Array> } {
  const files = new Map<string, Uint8Array>();
  return {
    kind: "memory",
    files,
    async put(p, bytes) {
      assertSafe(p);
      files.set(p, new Uint8Array(bytes));
    },
    async get(p) {
      assertSafe(p);
      return files.get(p) ?? null;
    },
    async remove(p) {
      assertSafe(p);
      files.delete(p);
    },
  };
}

// ---------------------------------------------------------------------------------------

export function createLocalAvatarStore(dir: string): AvatarStore {
  const root = path.resolve(dir);
  const resolve = (p: string): string => {
    assertSafe(p);
    const full = path.resolve(root, p);
    if (full !== root && !full.startsWith(root + path.sep)) throw new StorageError("path escapes the storage directory");
    return full;
  };
  return {
    kind: "local",
    async put(p, bytes) {
      const full = resolve(p);
      await mkdir(path.dirname(full), { recursive: true });
      await writeFile(full, bytes);
    },
    async get(p) {
      try {
        return new Uint8Array(await readFile(resolve(p)));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },
    async remove(p) {
      await rm(resolve(p), { force: true });
    },
  };
}

// ---------------------------------------------------------------------------------------

export interface SupabaseStoreOptions {
  /** Project URL, e.g. https://abcd1234.supabase.co */
  url: string;
  /** service_role key — SERVER ONLY. Never sent to a browser, never logged. */
  serviceKey: string;
  bucket: string;
  fetchImpl?: typeof fetch;
}

/**
 * Supabase Storage over its REST API with the service-role key (the bucket is private; the app serves the bytes).
 * Not verified against a live project in this repository's tests — see docs/HERO_PROFILE_PHOTOS.md.
 */
export function createSupabaseAvatarStore({ url, serviceKey, bucket, fetchImpl = fetch }: SupabaseStoreOptions): AvatarStore {
  const base = url.replace(/\/+$/, "");
  const objectUrl = (p: string): string => {
    assertSafe(p);
    return `${base}/storage/v1/object/${encodeURIComponent(bucket)}/${p.split("/").map(encodeURIComponent).join("/")}`;
  };
  const auth = { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey };
  /** Error messages carry the HTTP status only — never the URL, headers or key. */
  const failure = (what: string, res: Response) => new StorageError(`${what} failed (HTTP ${res.status})`, res.status);

  return {
    kind: "supabase",
    async put(p, bytes, mime) {
      const res = await fetchImpl(objectUrl(p), {
        method: "POST",
        headers: { ...auth, "Content-Type": mime, "x-upsert": "true", "Cache-Control": "max-age=31536000" },
        body: bytes as BodyInit,
      });
      if (!res.ok) throw failure("storing the image", res);
    },
    async get(p) {
      const res = await fetchImpl(objectUrl(p), { headers: auth });
      // Supabase answers a missing object with 400 or 404 depending on version.
      if (res.status === 404 || res.status === 400) return null;
      if (!res.ok) throw failure("reading the image", res);
      return new Uint8Array(await res.arrayBuffer());
    },
    async remove(p) {
      const res = await fetchImpl(objectUrl(p), { method: "DELETE", headers: auth });
      if (!res.ok && res.status !== 404 && res.status !== 400) throw failure("deleting the image", res);
    },
  };
}
